1	import { useQuery } from "@tanstack/react-query";
2	import { supabase } from "@/integrations/supabase/client";
3	import { useAuth } from "@/hooks/useAuth";
4	
5	const STALE_TIME = 5 * 60 * 1000; // 5 minutes
6	
7	// ─── Types ────────────────────────────────────────────────────────────────────
8	
9	export interface TimeToHireRow {
10	  job_id: string;
11	  title: string | null;
12	  job_created: string;
13	  first_hire_at: string | null;
14	  days_to_hire: number | null;
15	}
16	
17	export interface StageConversionRow {
18	  job_id: string;
19	  stage: string;
20	  count: number;
21	}
22	
23	export interface ScoreDistributionRow {
24	  bucket: string;
25	  count: number;
26	}
27	
28	export interface DailyActivityRow {
29	  activity_date: string;
30	  resumes_processed: number;
31	  jobs_active: number;
32	}
33	
34	export interface TopJobRow {
35	  job_id: string;
36	  title: string | null;
37	  candidate_count: number;
38	  avg_score: number;
39	  top_score: number;
40	}
41	
42	export interface ProductivityStats {
43	  total_jobs: number;
44	  total_candidates: number;
45	  total_credits_used: number;
46	  avg_candidates_per_job: number;
47	  jobs_last_30_days: number;
48	  candidates_last_30_days: number;
49	}
50	
51	// Aggregated funnel: stage → total across all jobs for this user
52	export interface FunnelItem {
53	  stage: string;
54	  count: number;
55	  label: string;
56	}
57	
58	// ─── Hooks ────────────────────────────────────────────────────────────────────
59	
60	export function useTimeToHire() {
61	  const { user } = useAuth();
62	  return useQuery<TimeToHireRow[]>({
63	    queryKey: ["analytics_time_to_hire", user?.id],
64	    enabled: !!user,
65	    staleTime: STALE_TIME,
66	    queryFn: async () => {
67	      const { data, error } = await (supabase as any)
68	        .from("v_time_to_hire")
69	        .select("job_id, title, job_created, first_hire_at, days_to_hire")
70	        .eq("user_id", user!.id)
71	        .not("days_to_hire", "is", null);
72	      if (error) throw new Error(error.message);
73	      return (data ?? []) as TimeToHireRow[];
74	    },
75	  });
76	}
77	
78	export function useStageConversion() {
79	  const { user } = useAuth();
80	  return useQuery<FunnelItem[]>({
81	    queryKey: ["analytics_stage_conversion", user?.id],
82	    enabled: !!user,
83	    staleTime: STALE_TIME,
84	    queryFn: async () => {
85	      const { data, error } = await (supabase as any)
86	        .from("v_stage_conversion")
87	        .select("stage, count")
88	        .eq("user_id", user!.id);
89	      if (error) throw new Error(error.message);
90	
91	      const rows = (data ?? []) as StageConversionRow[];
92	
93	      // Aggregate counts across all jobs per stage
94	      const stageTotals: Record<string, number> = {};
95	      for (const row of rows) {
96	        stageTotals[row.stage] = (stageTotals[row.stage] ?? 0) + row.count;
97	      }
98	
99	      const STAGE_ORDER = [
100	        { key: "applied",   label: "Applied" },
101	        { key: "screened",  label: "Screened" },
102	        { key: "interview", label: "Interview" },
103	        { key: "offer",     label: "Offer" },
104	        { key: "hired",     label: "Hired" },
105	      ];
106	
107	      return STAGE_ORDER.map(({ key, label }) => ({
108	        stage: key,
109	        label,
110	        count: stageTotals[key] ?? 0,
111	      }));
112	    },
113	  });
114	}
115	
116	export function useScoreDistribution() {
117	  const { user } = useAuth();
118	  return useQuery<ScoreDistributionRow[]>({
119	    queryKey: ["analytics_score_distribution", user?.id],
120	    enabled: !!user,
121	    staleTime: STALE_TIME,
122	    queryFn: async () => {
123	      const { data, error } = await (supabase as any)
124	        .from("v_score_distribution")
125	        .select("bucket, count")
126	        .eq("user_id", user!.id)
127	        .order("bucket");
128	      if (error) throw new Error(error.message);
129	
130	      // Ensure all 10 buckets are present even if count=0
131	      const BUCKETS = [
132	        "0-9","10-19","20-29","30-39","40-49",
133	        "50-59","60-69","70-79","80-89","90-100",
134	      ];
135	      const byBucket: Record<string, number> = {};
136	      for (const row of (data ?? []) as ScoreDistributionRow[]) {
137	        byBucket[row.bucket] = row.count;
138	      }
139	      return BUCKETS.map((b) => ({ bucket: b, count: byBucket[b] ?? 0 }));
140	    },
141	  });
142	}
143	
144	export function useDailyActivity() {
145	  const { user } = useAuth();
146	  return useQuery<DailyActivityRow[]>({
147	    queryKey: ["analytics_daily_activity", user?.id],
148	    enabled: !!user,
149	    staleTime: STALE_TIME,
150	    queryFn: async () => {
151	      const { data, error } = await (supabase as any)
152	        .from("v_daily_activity")
153	        .select("activity_date, resumes_processed, jobs_active")
154	        .eq("user_id", user!.id)
155	        .order("activity_date");
156	      if (error) throw new Error(error.message);
157	      return (data ?? []) as DailyActivityRow[];
158	    },
159	  });
160	}
161	
162	export function useTopJobs() {
163	  const { user } = useAuth();
164	  return useQuery<TopJobRow[]>({
165	    queryKey: ["analytics_top_jobs", user?.id],
166	    enabled: !!user,
167	    staleTime: STALE_TIME,
168	    queryFn: async () => {
169	      const { data, error } = await (supabase as any)
170	        .from("v_top_jobs")
171	        .select("job_id, title, candidate_count, avg_score, top_score")
172	        .eq("user_id", user!.id)
173	        .order("avg_score", { ascending: false })
174	        .limit(10);
175	      if (error) throw new Error(error.message);
176	      return (data ?? []) as TopJobRow[];
177	    },
178	  });
179	}
180	
181	export function useProductivityStats() {
182	  const { user } = useAuth();
183	  return useQuery<ProductivityStats>({
184	    queryKey: ["analytics_productivity", user?.id],
185	    enabled: !!user,
186	    staleTime: STALE_TIME,
187	    queryFn: async () => {
188	      const { data, error } = await (supabase as any).rpc("user_productivity_stats", {
189	        p_user_id: user!.id,
190	      });
191	      if (error) throw new Error(error.message);
192	      // RPC returns an array with one row
193	      const row = Array.isArray(data) ? data[0] : data;
194	      return (row ?? {
195	        total_jobs: 0,
196	        total_candidates: 0,
197	        total_credits_used: 0,
198	        avg_candidates_per_job: 0,
199	        jobs_last_30_days: 0,
200	        candidates_last_30_days: 0,
201	      }) as ProductivityStats;
202	    },
203	  });
204	}
