1	import { Users } from "lucide-react";
2	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
3	import { Skeleton } from "@/components/ui/skeleton";
4	import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from "recharts";
5	import { useStageConversion } from "@/hooks/useAnalytics";
6	
7	const STAGE_COLORS: Record<string, string> = {
8	  applied:   "#6366f1",
9	  screened:  "#8b5cf6",
10	  interview: "#a78bfa",
11	  offer:     "#c4b5fd",
12	  hired:     "#22c55e",
13	};
14	
15	function ConversionRate({ from, to }: { from: number; to: number }) {
16	  if (from === 0) return null;
17	  const rate = Math.round((to / from) * 100);
18	  return (
19	    <span className="text-[10px] text-muted-foreground ml-1">({rate}%)</span>
20	  );
21	}
22	
23	export function StageFunnel() {
24	  const { data, isLoading, error } = useStageConversion();
25	  const rows = data ?? [];
26	  const totalApplied = rows[0]?.count ?? 0;
27	
28	  return (
29	    <Card className="border border-border/60 shadow-sm">
30	      <CardHeader className="pb-2 px-5 pt-4">
31	        <CardTitle className="text-sm font-semibold">Stage Conversion Funnel</CardTitle>
32	        <CardDescription className="text-xs">
33	          Candidates at each pipeline stage across all jobs
34	        </CardDescription>
35	      </CardHeader>
36	      <CardContent className="px-4 pb-4">
37	        {isLoading ? (
38	          <div className="space-y-2">
39	            <Skeleton className="h-4 w-36" />
40	            <Skeleton className="h-[200px] w-full rounded-lg" />
41	          </div>
42	        ) : error ? (
43	          <div className="flex flex-col items-center justify-center h-[200px] gap-2">
44	            <Users className="h-7 w-7 text-muted-foreground/40" />
45	            <p className="text-xs text-muted-foreground">Could not load funnel data</p>
46	          </div>
47	        ) : totalApplied === 0 ? (
48	          <div className="flex flex-col items-center justify-center h-[200px] gap-2 text-center">
49	            <Users className="h-7 w-7 text-muted-foreground/40" />
50	            <p className="text-xs text-muted-foreground max-w-[200px]">
51	              Start moving candidates through pipeline stages to see conversion rates here.
52	            </p>
53	          </div>
54	        ) : (
55	          <>
56	            <ResponsiveContainer width="100%" height={200}>
57	              <BarChart
58	                data={rows}
59	                margin={{ top: 4, right: 8, left: -20, bottom: 0 }}
60	              >
61	                <CartesianGrid
62	                  strokeDasharray="3 3"
63	                  stroke="hsl(var(--border))"
64	                  vertical={false}
65	                />
66	                <XAxis
67	                  dataKey="label"
68	                  tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
69	                  axisLine={false}
70	                  tickLine={false}
71	                />
72	                <YAxis
73	                  tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
74	                  axisLine={false}
75	                  tickLine={false}
76	                  allowDecimals={false}
77	                />
78	                <Tooltip
79	                  contentStyle={{
80	                    backgroundColor: "hsl(var(--popover))",
81	                    border: "1px solid hsl(var(--border))",
82	                    borderRadius: 8,
83	                    fontSize: 12,
84	                  }}
85	                  cursor={{ fill: "hsl(var(--muted))" }}
86	                  formatter={(value: number, _name: string, props: { payload?: { label?: string } }) => [
87	                    value,
88	                    props?.payload?.label ?? "Candidates",
89	                  ]}
90	                />
91	                <Bar dataKey="count" radius={[4, 4, 0, 0]}>
92	                  {rows.map((row) => (
93	                    <Cell
94	                      key={row.stage}
95	                      fill={STAGE_COLORS[row.stage] ?? "#6366f1"}
96	                    />
97	                  ))}
98	                </Bar>
99	              </BarChart>
100	            </ResponsiveContainer>
101	
102	            {/* Conversion rates below chart */}
103	            <div className="flex items-center justify-between mt-3 px-1">
104	              {rows.map((row, idx) => (
105	                <div key={row.stage} className="flex flex-col items-center text-center">
106	                  <span className="text-xs font-medium text-foreground">{row.count}</span>
107	                  {idx > 0 && (
108	                    <ConversionRate from={rows[idx - 1].count} to={row.count} />
109	                  )}
110	                  {idx === 0 && (
111	                    <span className="text-[10px] text-muted-foreground">total</span>
112	                  )}
113	                </div>
114	              ))}
115	            </div>
116	          </>
117	        )}
118	      </CardContent>
119	    </Card>
120	  );
121	}
