1	import { CalendarDays } from "lucide-react";
2	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
3	import { Skeleton } from "@/components/ui/skeleton";
4	import { useDailyActivity } from "@/hooks/useAnalytics";
5	import type { DailyActivityRow } from "@/hooks/useAnalytics";
6	
7	// ─── Build 90-day grid ────────────────────────────────────────────────────────
8	
9	function buildGrid(rows: DailyActivityRow[]) {
10	  const byDate: Record<string, number> = {};
11	  for (const row of rows) {
12	    byDate[row.activity_date.slice(0, 10)] = row.resumes_processed;
13	  }
14	
15	  const today = new Date();
16	  today.setHours(0, 0, 0, 0);
17	
18	  const days: { date: string; count: number; weekday: number }[] = [];
19	  for (let i = 89; i >= 0; i--) {
20	    const d = new Date(today.getTime() - i * 86400000);
21	    const key = d.toISOString().slice(0, 10);
22	    days.push({
23	      date: key,
24	      count: byDate[key] ?? 0,
25	      weekday: d.getDay(), // 0=Sun
26	    });
27	  }
28	  return days;
29	}
30	
31	// ─── Intensity colour ─────────────────────────────────────────────────────────
32	
33	function intensityClass(count: number, max: number): string {
34	  if (count === 0) return "bg-muted/40 border border-border/30";
35	  const ratio = count / Math.max(max, 1);
36	  if (ratio < 0.25) return "bg-indigo-200 dark:bg-indigo-900/60";
37	  if (ratio < 0.5)  return "bg-indigo-400 dark:bg-indigo-700";
38	  if (ratio < 0.75) return "bg-indigo-500 dark:bg-indigo-600";
39	  return "bg-indigo-600 dark:bg-indigo-500";
40	}
41	
42	// ─── Tooltip (pure div, no lib) ───────────────────────────────────────────────
43	
44	interface CellProps {
45	  date: string;
46	  count: number;
47	  max: number;
48	}
49	
50	function HeatCell({ date, count, max }: CellProps) {
51	  const label = new Date(date + "T00:00:00").toLocaleDateString("default", {
52	    month: "short",
53	    day: "numeric",
54	  });
55	  const title =
56	    count === 0
57	      ? `${label}: no activity`
58	      : `${label}: ${count} candidate${count !== 1 ? "s" : ""} processed`;
59	
60	  return (
61	    <div
62	      className={`w-3 h-3 rounded-[2px] cursor-default ${intensityClass(count, max)}`}
63	      title={title}
64	    />
65	  );
66	}
67	
68	// ─── Week-day labels ──────────────────────────────────────────────────────────
69	const DAY_LABELS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
70	
71	// ─── Main component ───────────────────────────────────────────────────────────
72	
73	export function ActivityHeatmap() {
74	  const { data, isLoading, error } = useDailyActivity();
75	
76	  const rows = data ?? [];
77	  const grid = buildGrid(rows);
78	  const maxCount = Math.max(...grid.map((d) => d.count), 1);
79	  const totalProcessed = rows.reduce((s, r) => s + r.resumes_processed, 0);
80	
81	  // Group into weeks (columns of 7 days, starting from first day)
82	  const weeks: typeof grid[number][][] = [];
83	  let week: typeof grid[number][] = [];
84	
85	  // Pad start so week starts on Sunday
86	  const firstWeekday = grid[0]?.weekday ?? 0;
87	  for (let i = 0; i < firstWeekday; i++) {
88	    week.push({ date: "", count: -1, weekday: i }); // empty padding cells
89	  }
90	
91	  for (const day of grid) {
92	    week.push(day);
93	    if (week.length === 7) {
94	      weeks.push(week);
95	      week = [];
96	    }
97	  }
98	  if (week.length > 0) {
99	    while (week.length < 7) week.push({ date: "", count: -1, weekday: week.length });
100	    weeks.push(week);
101	  }
102	
103	  return (
104	    <Card className="border border-border/60 shadow-sm">
105	      <CardHeader className="pb-2 px-5 pt-4">
106	        <CardTitle className="text-sm font-semibold">Activity Heatmap</CardTitle>
107	        <CardDescription className="text-xs">
108	          {totalProcessed > 0
109	            ? `${totalProcessed} candidates processed in the last 90 days`
110	            : "Candidate processing activity over the last 90 days"}
111	        </CardDescription>
112	      </CardHeader>
113	      <CardContent className="px-5 pb-5">
114	        {isLoading ? (
115	          <Skeleton className="h-[100px] w-full rounded-lg" />
116	        ) : error ? (
117	          <div className="flex flex-col items-center justify-center h-[100px] gap-2">
118	            <CalendarDays className="h-7 w-7 text-muted-foreground/40" />
119	            <p className="text-xs text-muted-foreground">Could not load activity data</p>
120	          </div>
121	        ) : totalProcessed === 0 ? (
122	          <div className="flex flex-col items-center justify-center py-6 gap-2 text-center">
123	            <CalendarDays className="h-7 w-7 text-muted-foreground/40" />
124	            <p className="text-xs text-muted-foreground max-w-[220px]">
125	              Start creating jobs and ranking candidates to see your hiring activity here.
126	            </p>
127	          </div>
128	        ) : (
129	          <div className="overflow-x-auto">
130	            <div className="inline-flex gap-0">
131	              {/* Day-of-week labels */}
132	              <div className="flex flex-col gap-[2px] mr-1.5 pt-[18px]">
133	                {DAY_LABELS.map((d) => (
134	                  <span
135	                    key={d}
136	                    className="text-[9px] text-muted-foreground leading-none h-3 flex items-center"
137	                  >
138	                    {d}
139	                  </span>
140	                ))}
141	              </div>
142	
143	              {/* Grid columns = weeks */}
144	              <div className="flex flex-col">
145	                {/* Month labels row */}
146	                <div className="flex gap-[2px] mb-1">
147	                  {weeks.map((week, wi) => {
148	                    // Show month label when month changes
149	                    const firstReal = week.find((d) => d.date !== "");
150	                    if (!firstReal) return <div key={wi} className="w-3" />;
151	                    const isFirstOfMonth = firstReal.date.slice(8, 10) <= "07";
152	                    const monthLabel = isFirstOfMonth
153	                      ? new Date(firstReal.date + "T00:00:00").toLocaleString("default", { month: "short" })
154	                      : "";
155	                    return (
156	                      <div key={wi} className="w-3 text-[9px] text-muted-foreground leading-none">
157	                        {monthLabel}
158	                      </div>
159	                    );
160	                  })}
161	                </div>
162	
163	                {/* Day rows */}
164	                {DAY_LABELS.map((_, dayIdx) => (
165	                  <div key={dayIdx} className="flex gap-[2px] mb-[2px]">
166	                    {weeks.map((week, wi) => {
167	                      const day = week[dayIdx];
168	                      if (!day || day.count === -1 || !day.date) {
169	                        return <div key={wi} className="w-3 h-3" />;
170	                      }
171	                      return (
172	                        <HeatCell
173	                          key={wi}
174	                          date={day.date}
175	                          count={day.count}
176	                          max={maxCount}
177	                        />
178	                      );
179	                    })}
180	                  </div>
181	                ))}
182	              </div>
183	            </div>
184	
185	            {/* Legend */}
186	            <div className="flex items-center gap-1.5 mt-3">
187	              <span className="text-[10px] text-muted-foreground">Less</span>
188	              {[0, 0.2, 0.5, 0.75, 1].map((ratio, i) => (
189	                <div
190	                  key={i}
191	                  className={`w-3 h-3 rounded-[2px] ${intensityClass(Math.round(ratio * maxCount), maxCount)}`}
192	                />
193	              ))}
194	              <span className="text-[10px] text-muted-foreground">More</span>
195	            </div>
196	          </div>
197	        )}
198	      </CardContent>
199	    </Card>
200	  );
201	}
