1	import {
2	  Briefcase,
3	  Users,
4	  Coins,
5	  BarChart2,
6	  Clock,
7	  Zap,
8	} from "lucide-react";
9	import { Card, CardContent } from "@/components/ui/card";
10	import { Skeleton } from "@/components/ui/skeleton";
11	import { useProductivityStats } from "@/hooks/useAnalytics";
12	import type { ProductivityStats } from "@/hooks/useAnalytics";
13	
14	interface StatTileProps {
15	  label: string;
16	  value: string | number;
17	  sub: string;
18	  icon: React.ReactNode;
19	  loading: boolean;
20	  accent?: string;
21	}
22	
23	function StatTile({ label, value, sub, icon, loading, accent = "text-muted-foreground/60" }: StatTileProps) {
24	  if (loading) {
25	    return (
26	      <Card className="border border-border/60 shadow-sm">
27	        <CardContent className="pt-4 pb-3 px-4">
28	          <Skeleton className="h-3 w-24 mb-3" />
29	          <Skeleton className="h-7 w-16 mb-1" />
30	          <Skeleton className="h-2.5 w-20" />
31	        </CardContent>
32	      </Card>
33	    );
34	  }
35	  return (
36	    <Card className="border border-border/60 shadow-sm">
37	      <CardContent className="pt-4 pb-3 px-4">
38	        <div className="flex items-start justify-between mb-1.5">
39	          <p className="text-xs font-medium text-muted-foreground">{label}</p>
40	          <span className={accent}>{icon}</span>
41	        </div>
42	        <p className="text-2xl font-bold text-foreground leading-none">{value}</p>
43	        <p className="text-[10px] text-muted-foreground mt-1">{sub}</p>
44	      </CardContent>
45	    </Card>
46	  );
47	}
48	
49	function buildTiles(stats: ProductivityStats | undefined, loading: boolean) {
50	  return [
51	    {
52	      label: "Total Jobs",
53	      value: stats?.total_jobs ?? 0,
54	      sub: "All time",
55	      icon: <Briefcase className="h-4 w-4" />,
56	    },
57	    {
58	      label: "Total Candidates",
59	      value: stats?.total_candidates ?? 0,
60	      sub: "All time",
61	      icon: <Users className="h-4 w-4" />,
62	    },
63	    {
64	      label: "Credits Used",
65	      value: stats?.total_credits_used ?? 0,
66	      sub: "All time",
67	      icon: <Coins className="h-4 w-4" />,
68	    },
69	    {
70	      label: "Avg Candidates / Job",
71	      value: stats?.avg_candidates_per_job ?? 0,
72	      sub: "Per posting",
73	      icon: <BarChart2 className="h-4 w-4" />,
74	    },
75	    {
76	      label: "Jobs (Last 30 days)",
77	      value: stats?.jobs_last_30_days ?? 0,
78	      sub: "Recent activity",
79	      icon: <Clock className="h-4 w-4" />,
80	    },
81	    {
82	      label: "Candidates (Last 30 days)",
83	      value: stats?.candidates_last_30_days ?? 0,
84	      sub: "Recent activity",
85	      icon: <Zap className="h-4 w-4" />,
86	    },
87	  ].map((tile) => ({ ...tile, loading }));
88	}
