77	function rangeToDate(range: RangeOption): Date | null {
78	  const now = new Date();
79	  if (range === "Last 30 days") {
80	    return new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
81	  }
82	  if (range === "Last 90 days") {
83	    return new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
84	  }
85	  if (range === "Last 6 months") {
86	    return new Date(now.getTime() - 180 * 24 * 60 * 60 * 1000);
87	  }
88	  return null;
89	}
