147	    queryFn: async (): Promise<ReportsData> => {
148	      const since = rangeToDate(range);
149	
150	      // ── 1. Jobs in range ──
151	      let jobsQ = (supabase as any)
152	        .from("jobs")
153	        .select("id, title, status, created_at")
154	        .eq("user_id", user!.id)
155	        .order("created_at", { ascending: false });
156	
157	      if (since) {
158	        jobsQ = jobsQ.gte("created_at", since.toISOString());
159	      }
160	
161	      const { data: jobs, error: jobsErr } = await jobsQ;
162	      if (jobsErr) throw new Error(jobsErr.message);
163	
164	      const jobIds: string[] = (jobs ?? []).map((j: any) => j.id);
165	
166	      // ── 2. Resumes for those jobs ──
167	      let resumes: any[] = [];
168	      if (jobIds.length > 0) {
169	        const { data: rData, error: rErr } = await (supabase as any)
170	          .from("resumes")
171	          .select("id, job_id, status, created_at")
172	          .in("job_id", jobIds);
173	        if (rErr) throw new Error(rErr.message);
