188	
189	      // ── Derived stats ──
190	      const totalJobs = (jobs ?? []).length;
191	      const activeCandidates = resumes.filter((r: any) => r.status !== "failed").length;
192	      const scores = results.map((r: any) => r.overall_score as number).filter(Boolean);
193	      const avgScore = scores.length > 0 ? scores.reduce((a: number, b: number) => a + b, 0) / scores.length : 0;
194	
195	      // Avg time to hire: time between job created_at and last resume done status
196	      // Approximate with avg time between job creation and last resume processed
197	      let totalHours = 0;
198	      let jobsWithResumes = 0;
199	      for (const job of jobs ?? []) {
200	        const jobResumes = resumes.filter((r: any) => r.job_id === job.id && r.status === "done");
201	        if (jobResumes.length > 0) {
202	          const latest = jobResumes.reduce((max: any, r: any) =>
203	            new Date(r.created_at) > new Date(max.created_at) ? r : max
204	          );
205	          const diffMs = new Date(latest.created_at).getTime() - new Date(job.created_at).getTime();
206	          totalHours += diffMs / (1000 * 60 * 60);
