1	/**
2	 * Rankora Chrome Extension — content-script.js
3	 *
4	 * Injected into LinkedIn and GitHub profile pages.
5	 * Listens for { action: 'extractProfile' } from popup and returns structured
6	 * candidate data.
7	 *
8	 * Uses multiple selector fallbacks because LinkedIn/GitHub change their DOM
9	 * frequently. Returns null fields gracefully — never throws.
10	 */
11	
12	'use strict';
13	
14	// ─── Helpers ─────────────────────────────────────────────────────────────────
15	
16	/**
17	 * Try each selector in order, return trimmed text of first match or null.
18	 */
19	function trySelectors(selectors) {
20	  for (const sel of selectors) {
21	    try {
22	      const el = document.querySelector(sel);
23	      if (el) {
24	        const text = el.innerText || el.textContent || '';
25	        const trimmed = text.trim().replace(/\s+/g, ' ');
26	        if (trimmed) return trimmed;
27	      }
28	    } catch (_) {
29	      // Ignore invalid selectors — continue trying
30	    }
31	  }
32	  return null;
33	}
34	
35	/**
36	 * Try each selector, return array of trimmed text values.
37	 */
38	function trySelectorsAll(selectors) {
39	  for (const sel of selectors) {
40	    try {
41	      const els = document.querySelectorAll(sel);
42	      if (els.length > 0) {
43	        const values = Array.from(els)
44	          .map((el) => (el.innerText || el.textContent || '').trim().replace(/\s+/g, ' '))
45	          .filter(Boolean);
46	        if (values.length > 0) return values;
47	      }
48	    } catch (_) {
49	      // Ignore
50	    }
51	  }
52	  return [];
53	}
54	
55	// ─── LinkedIn Extractor ───────────────────────────────────────────────────────
56	
57	function extractLinkedIn() {
58	  const name = trySelectors([
59	    'h1.text-heading-xlarge',
60	    '.pv-text-details__left-panel h1',
61	    'h1[class*="heading"]',
62	    '.top-card-layout__title',
63	    '.profile-info-subheader h1',
64	    '.artdeco-entity-lockup__title',
65	    // Generic fallback — first h1 on page
66	    'h1',
67	  ]);
68	
69	  const title = trySelectors([
70	    '.text-body-medium[class*="break-words"]',
71	    '.pv-text-details__left-panel .text-body-medium',
72	    '.top-card-layout__headline',
73	    '.ph5.pb5 .mt2 .text-body-medium',
74	    '.profile-info-subheader .text-body-small',
75	    '.artdeco-entity-lockup__subtitle',
76	  ]);
77	
78	  // Company: the "at X" part of headline, or Experience section top entry
79	  const companyRaw = trySelectors([
80	    '.pv-text-details__right-panel .inline-show-more-text',
81	    '.pv-text-details__right-panel li:first-child span',
82	    '.pv-position-entity .t-14:first-child',
83	    '.experience-section .pv-entity__secondary-title',
84	    '.pv-recent-activity-item__detail span',
85	    '[aria-label*="Current company"]',
86	  ]);
87	
88	  // Try parsing "at Company" from headline
89	  let company = companyRaw;
90	  if (!company && title) {
91	    const atMatch = title.match(/\bat\s+(.+)$/i);
92	    if (atMatch) company = atMatch[1].trim();
93	  }
94	
95	  const location = trySelectors([
96	    '.text-body-small.inline.t-black--light',
97	    '.pv-text-details__left-panel .text-body-small:not(.inline)',
98	    '.profile-info-subheader .text-body-small',
99	    '.top-card-layout__first-subline',
100	    '[class*="top-card"] .text-body-small',
101	  ]);
102	
103	  const bio = trySelectors([
104	    '.pv-shared-text-with-see-more span[aria-hidden="true"]',
105	    '.pv-about__summary-text .inline-show-more-text',
106	    '.inline-show-more-text',
107	    '[data-field="summary"] span',
108	  ]);
109	
110	  return {
111	    name,
112	    title,
113	    company,
114	    location,
115	    bio,
116	    profile_url: window.location.href.split('?')[0], // strip query params
117	    source: 'linkedin',
118	  };
119	}
120	
121	// ─── GitHub Extractor ─────────────────────────────────────────────────────────
122	
123	function extractGitHub() {
124	  // Name: prefer display name over username
125	  const name = trySelectors([
126	    '.p-name.vcard-fullname',
127	    'h1.vcard-names .p-name',
128	    '.p-name',
129	    'span[itemprop="name"]',
130	    '.vcard-fullname',
131	  ]);
132	
133	  const username = trySelectors([
134	    '.p-nickname',
135	    'span[itemprop="additionalName"]',
136	    '.vcard-username',
137	  ]);
138	
139	  // Use display name if present, else fallback to username
140	  const resolvedName = name || username;
141	
142	  const title = trySelectors([
143	    '.p-label',
144	    '.user-profile-bio .p-label',
145	    '.user-bio.p-label',
146	  ]);
147	
148	  const company = trySelectors([
149	    '.vcard-detail [itemprop="worksFor"]',
150	    '.vcard-details [itemprop="worksFor"] span',
151	    '.vcard-detail:nth-child(1) span',
152	    '.octicon-organization + span',
153	    '[aria-label*="Organization"] span',
154	  ]);
155	
156	  const location = trySelectors([
157	    '.vcard-detail [itemprop="homeLocation"]',
158	    '.vcard-details [itemprop="homeLocation"] span',
159	    '.octicon-location + span',
160	    '[aria-label*="Location"] span',
161	  ]);
162	
163	  const bio = trySelectors([
164	    '.p-note.user-profile-bio .readable-content',
165	    '.p-note.user-profile-bio',
166	    '.user-profile-bio > div',
167	    '.user-bio',
168	  ]);
169	
170	  // Stats (optional — for enrichment)
171	  const followers = trySelectors([
172	    '.js-profile-editable-area .d-flex .Link--secondary:first-child .text-bold',
173	    'a[href$="followers"] .text-bold',
174	  ]);
175	
176	  return {
177	    name: resolvedName,
178	    title,
179	    company: company ? company.replace(/^@/, '').trim() : null,
180	    location,
181	    bio,
182	    followers,
183	    profile_url: window.location.href.split('?')[0],
184	    source: 'github',
185	  };
186	}
187	
188	// ─── Message Listener ─────────────────────────────────────────────────────────
189	
190	chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
191	  if (message.action !== 'extractProfile') return false;
192	
193	  try {
194	    const url = window.location.href;
195	
196	    let profile;
197	    if (/linkedin\.com\/in\//.test(url)) {
198	      profile = extractLinkedIn();
199	    } else if (/github\.com\//.test(url)) {
200	      profile = extractGitHub();
201	    } else {
202	      sendResponse({ error: 'unsupported_page', name: null });
203	      return true;
204	    }
205	
206	    // Validate — at minimum we need a name
207	    if (!profile.name) {
208	      // Last resort: try og:title or document.title
209	      const ogTitle = document.querySelector('meta[property="og:title"]');
210	      if (ogTitle) {
211	        profile.name = ogTitle.getAttribute('content')?.split('|')[0]?.trim() || null;
212	      } else {
213	        profile.name = document.title?.split('|')[0]?.split('-')[0]?.trim() || null;
214	      }
215	    }
216	
217	    sendResponse(profile);
218	  } catch (err) {
219	    sendResponse({ error: err.message, name: null });
220	  }
221	
222	  return true; // Keep channel open for async
223	});
224	
225	// Signal that content script is ready
226	if (typeof window.__rankoraContentScriptLoaded === 'undefined') {
227	  window.__rankoraContentScriptLoaded = true;
228	}
