222	async function captureCandidate() {
223	  if (!currentProfile) return;
224	
225	  clearError('capture-error');
226	  setButtonLoading('btn-capture', true);
227	
228	  try {
229	    const stored = await getStorage(['rankora_api_key', 'rankora_api_base']);
230	    const apiKey = stored.rankora_api_key;
231	    if (!apiKey) {
232	      showLoginView();
233	      return;
234	    }
235	    const base = stored.rankora_api_base || DEFAULT_API_BASE;
236	
237	    const endpoint = `${base}${CAPTURE_FUNCTION}`;
238	
239	    const response = await fetch(endpoint, {
240	      method: 'POST',
241	      headers: {
242	        'Content-Type': 'application/json',
243	        'Authorization': `Bearer ${apiKey}`,
244	      },
245	      body: JSON.stringify({
246	        name: currentProfile.name,
247	        title: currentProfile.title,
248	        company: currentProfile.company,
249	        location: currentProfile.location,
250	        bio: currentProfile.bio,
251	        profile_url: currentProfile.profile_url,
252	        source: currentProfile.source,
253	      }),
254	    });
255	
256	    const data = await response.json().catch(() => ({}));
257	
258	    if (!response.ok) {
259	      if (response.status === 401) {
260	        showError('capture-error', 'API key is invalid or revoked. Please reconnect.');
261	        show('capture-error');
262	        return;
263	      }
264	      if (response.status === 409) {
265	        showError('capture-error', 'This candidate is already in your talent pool.');
266	        show('capture-error');
267	        return;
268	      }
269	      throw new Error(data.error || `Server error (${response.status})`);
270	    }
271	
272	    showSuccessState(currentProfile);
273	  } catch (err) {
274	    if (err.name === 'TypeError' && err.message.includes('fetch')) {
275	      showError('capture-error', 'Network error. Check your internet connection and try again.');
276	    } else {
277	      showError('capture-error', err.message || 'Failed to capture candidate. Please try again.');
278	    }
279	    show('capture-error');
280	  } finally {
281	    setButtonLoading('btn-capture', false);
282	  }
283	}
