295	    $('input-api-key').classList.add('error');
296	    return;
297	  }
298	
299	  if (!rawKey.startsWith('rk_live_')) {
300	    showError('api-key-error', 'Invalid format. API keys start with rk_live_');
301	    $('input-api-key').classList.add('error');
302	    return;
303	  }
304	
305	  setButtonLoading('btn-save-key', true);
306	
307	  try {
308	    // Verify the key is valid by calling the edge function with a test request
309	    const stored = await getStorage(['rankora_api_base']);
310	    const base = stored.rankora_api_base || DEFAULT_API_BASE;
311	
312	    const verifyResp = await fetch(`${base}/functions/v1/extension-capture/verify`, {
313	      method: 'POST',
