329	    // Key is valid — save it
330	    await setStorage({ rankora_api_key: rawKey, rankora_api_base: base });
331	    showMainView();
332	  } catch (err) {
333	    if (err.name === 'TypeError' && err.message.includes('fetch')) {
334	      showError('api-key-error', 'Network error. Check your connection and try again.');
335	    } else {
336	      showError('api-key-error', err.message || 'Could not verify API key.');
337	    }
338	    $('input-api-key').classList.add('error');
339	  } finally {
340	    setButtonLoading('btn-save-key', false);
341	  }
342	}
