1	/**
2	 * Rankora Chrome Extension — background.js (Service Worker)
3	 *
4	 * Minimal service worker for Manifest V3.
5	 * Handles:
6	 *  - Extension icon click state (badge text to indicate unsaved captures)
7	 *  - Tab update listener to reset badge when user navigates
8	 *  - API retry queue (future: offline support)
9	 *
10	 * Keep this file lean — heavy logic lives in popup.js and content-script.js.
11	 */
12	
13	'use strict';
14	
15	// ─── Install / Activate ───────────────────────────────────────────────────────
16	
17	self.addEventListener('install', () => {
18	  self.skipWaiting();
19	});
20	
21	self.addEventListener('activate', () => {
22	  self.clients.claim();
23	});
