25	// ─── Tab listener — update badge when navigating to supported pages ───────────
26	
27	const SUPPORTED_PATTERNS = [
28	  /linkedin\.com\/in\//,
29	  /github\.com\/[^/]+\/?$/,
30	];
31	
32	function isSupportedPage(url) {
33	  if (!url) return false;
34	  return SUPPORTED_PATTERNS.some((re) => re.test(url));
35	}
36	
37	chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
38	  if (changeInfo.status !== 'complete') return;
39	  if (!tab.url) return;
40	
41	  if (isSupportedPage(tab.url)) {
42	    // Show a subtle badge so user knows the extension is active on this page
43	    chrome.action.setBadgeText({ text: '', tabId });
44	    chrome.action.setBadgeBackgroundColor({ color: '#6366f1', tabId });
