51	
52	chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
53	  // Future: handle retry queue, offline captures, etc.
54	  if (message.action === 'ping') {
55	    sendResponse({ status: 'ok', version: '0.1.0' });
56	    return true;
