1	/**
2	 * extension-capture — Rankora Chrome Extension Capture API
3	 *
4	 * Accepts candidate profiles captured from LinkedIn / GitHub via the
5	 * Rankora Chrome Extension and stores them as resumes (candidate profiles)
6	 * in the user's talent pool.
7	 *
8	 * Auth: API key (Authorization: Bearer rk_live_...)
9	 *       Same validation as public-api — key_hash lookup in api_keys table.
10	 *
11	 * Routes:
12	 *   POST /extension-capture         — capture a candidate profile
13	 *   POST /extension-capture/verify  — verify API key only (used by popup on login)
14	 *
15	 * CORS: * (required for chrome-extension:// origin)
16	 */
17	
18	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
19	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
20	
21	// ─── CORS ─────────────────────────────────────────────────────────────────────
22	
23	const CORS_HEADERS = {
24	  "Access-Control-Allow-Origin": "*",
25	  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
26	  "Access-Control-Allow-Headers": "Authorization, Content-Type",
27	};
28	
29	// ─── Response helpers ─────────────────────────────────────────────────────────
30	
31	function json(data: unknown, status = 200): Response {
32	  return new Response(JSON.stringify(data), {
33	    status,
34	    headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
35	  });
36	}
37	
38	function error(message: string, status: number, code = "error"): Response {
39	  return json({ error: message, code }, status);
40	}
41	
42	// ─── API key auth (mirrors public-api pattern exactly) ────────────────────────
43	
44	async function hashKey(raw: string): Promise<string> {
45	  const encoder = new TextEncoder();
46	  const data = encoder.encode(raw);
47	  const digest = await crypto.subtle.digest("SHA-256", data);
48	  return Array.from(new Uint8Array(digest))
49	    .map((b) => b.toString(16).padStart(2, "0"))
50	    .join("");
51	}
52	
53	interface AuthResult {
54	  userId: string;
55	  keyId: string;
56	}
57	
58	async function authenticateRequest(
59	  req: Request,
60	  supabase: ReturnType<typeof createClient>
61	): Promise<{ auth: AuthResult | null; errorResponse: Response | null }> {
62	  const authHeader = req.headers.get("Authorization") ?? "";
63	  const match = authHeader.match(/^Bearer\s+(rk_live_[A-Za-z0-9]+)$/);
64	
65	  if (!match) {
66	    return {
67	      auth: null,
68	      errorResponse: error(
69	        "Missing or invalid API key. Include: Authorization: Bearer rk_live_...",
70	        401,
71	        "unauthorized"
72	      ),
73	    };
74	  }
75	
76	  const rawKey = match[1];
77	  const keyHash = await hashKey(rawKey);
78	
79	  const { data: keyRecord, error: keyErr } = await supabase
80	    .from("api_keys")
81	    .select("id, user_id, revoked")
82	    .eq("key_hash", keyHash)
83	    .single();
84	
85	  if (keyErr || !keyRecord) {
86	    return { auth: null, errorResponse: error("Invalid API key.", 401, "unauthorized") };
87	  }
88	
89	  if (keyRecord.revoked) {
90	    return {
91	      auth: null,
92	      errorResponse: error("This API key has been revoked.", 401, "key_revoked"),
93	    };
94	  }
95	
96	  // Update last_used_at (fire-and-forget)
97	  supabase
98	    .from("api_keys")
99	    .update({ last_used_at: new Date().toISOString() })
100	    .eq("id", keyRecord.id)
101	    .then(() => {})
102	    .catch(() => {});
103	
104	  return { auth: { userId: keyRecord.user_id, keyId: keyRecord.id }, errorResponse: null };
105	}
106	
107	// ─── Input validation ─────────────────────────────────────────────────────────
108	
109	interface CaptureBody {
110	  name?: string;
111	  title?: string;
112	  company?: string;
113	  location?: string;
114	  bio?: string;
115	  profile_url?: string;
116	  source?: string;
117	}
118	
119	function validateBody(body: unknown): { data: CaptureBody; validationError: string | null } {
120	  if (!body || typeof body !== "object") {
121	    return { data: {}, validationError: "Request body must be a JSON object." };
122	  }
123	
124	  const b = body as Record<string, unknown>;
125	
126	  const name = typeof b.name === "string" ? b.name.trim().slice(0, 255) : null;
127	  if (!name) {
128	    return { data: {}, validationError: "name is required." };
129	  }
130	
131	  const profileUrl = typeof b.profile_url === "string" ? b.profile_url.trim().slice(0, 2000) : null;
132	  if (!profileUrl) {
133	    return { data: {}, validationError: "profile_url is required." };
134	  }
135	
136	  // Validate profile_url is from a supported domain
137	  const allowedDomains = ["linkedin.com", "github.com"];
138	  const urlLower = profileUrl.toLowerCase();
139	  const isAllowed = allowedDomains.some((d) => urlLower.includes(d));
140	  if (!isAllowed) {
141	    return { data: {}, validationError: "profile_url must be from linkedin.com or github.com." };
142	  }
143	
144	  const source = typeof b.source === "string" ? b.source : "other";
145	  const validSources = ["linkedin", "github", "other"];
146	  const resolvedSource = validSources.includes(source) ? source : "other";
147	
148	  return {
149	    data: {
150	      name,
151	      title: typeof b.title === "string" ? b.title.trim().slice(0, 255) : undefined,
152	      company: typeof b.company === "string" ? b.company.trim().slice(0, 255) : undefined,
153	      location: typeof b.location === "string" ? b.location.trim().slice(0, 255) : undefined,
154	      bio: typeof b.bio === "string" ? b.bio.trim().slice(0, 2000) : undefined,
155	      profile_url: profileUrl,
156	      source: resolvedSource,
157	    },
158	    validationError: null,
159	  };
160	}
161	
162	// ─── Main handler ─────────────────────────────────────────────────────────────
163	
164	serve(async (req: Request) => {
165	  // Preflight
166	  if (req.method === "OPTIONS") {
167	    return new Response(null, { status: 204, headers: CORS_HEADERS });
168	  }
169	
170	  // Only accept POST
171	  if (req.method !== "POST") {
172	    return error("Method not allowed.", 405, "method_not_allowed");
173	  }
174	
175	  const supabase = createClient(
176	    Deno.env.get("SUPABASE_URL")!,
177	    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
178	  );
179	
180	  // Auth
181	  const { auth, errorResponse } = await authenticateRequest(req, supabase);
182	  if (!auth) return errorResponse!;
183	
184	  const { userId } = auth;
185	
186	  // Route: /verify — just returns 200 if auth passed
187	  const url = new URL(req.url);
188	  const path = url.pathname.replace(/\/functions\/v1\/extension-capture/, "").replace(/^\/extension-capture/, "");
189	
190	  if (path === "/verify" || path === "/verify/") {
191	    return json({ ok: true, user_id: userId });
192	  }
193	
194	  // Route: POST / — capture candidate
195	  let rawBody: unknown;
196	  try {
197	    rawBody = await req.json();
198	  } catch {
199	    return error("Invalid JSON body.", 400, "bad_request");
200	  }
201	
202	  const { data: captureData, validationError } = validateBody(rawBody);
203	  if (validationError) {
204	    return error(validationError, 400, "validation_error");
205	  }
206	
207	  // ── Duplicate check ─────────────────────────────────────────────────────────
208	  // Check if this profile_url already exists in resumes for this user
209	  // (via jobs owned by user or via existing candidate profile resumes)
210	  const { data: existing } = await supabase
211	    .from("resumes")
212	    .select("id, candidate_name")
213	    .filter("parsed_json->>profile_url", "eq", captureData.profile_url)
214	    .limit(1);
215	
216	  // Check if any of the existing resumes belong to this user's jobs
217	  if (existing && existing.length > 0) {
218	    const resumeId = existing[0].id;
219	    const { data: ownerCheck } = await supabase
220	      .from("resumes")
221	      .select("id, jobs!inner(user_id)")
222	      .eq("id", resumeId)
223	      .eq("jobs.user_id", userId)
224	      .limit(1);
225	
226	    if (ownerCheck && ownerCheck.length > 0) {
227	      return json(
228	        {
229	          success: false,
230	          error: "This candidate is already in your talent pool.",
231	          code: "duplicate",
232	          candidate_id: resumeId,
233	        },
234	        409
235	      );
236	    }
237	  }
238	
239	  // ── Create job for candidate pool (use sentinel job or create a "Talent Pool" job) ──
240	  // Look for an existing talent pool job for this user
241	  const TALENT_POOL_TITLE = "__rankora_talent_pool__";
242	
243	  let { data: poolJob } = await supabase
244	    .from("jobs")
245	    .select("id")
246	    .eq("user_id", userId)
247	    .eq("title", TALENT_POOL_TITLE)
248	    .limit(1)
249	    .single();
250	
251	  if (!poolJob) {
252	    // Create the sentinel talent pool job (hidden from UI via title prefix)
253	    const { data: newJob, error: jobErr } = await supabase
254	      .from("jobs")
255	      .insert({
256	        user_id: userId,
257	        title: TALENT_POOL_TITLE,
258	        job_description: "Chrome extension talent pool capture job. Do not delete.",
